// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 collectAmt) public {
        // Bound minSum to a non-zero value to avoid trivial cases
        vm.assume(minSum > 0 && minSum <= type(uint256).max);
        // Ensure collectAmt is valid: not too large to cause overflow in balance checks
        vm.assume(collectAmt <= type(uint256).max);

        // Set the minimum sum
        c.SetMinSum(minSum);
        // Initialize the contract to prevent further changes to MinSum
        c.Initialized();

        // Provide some ETH to the contract so balance can be sufficient
        vm.deal(address(c), 1 ether);

        // Attempt Collect – may revert if balances[msg.sender] < MinSum or < collectAmt
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // Rule: MinSum must equal the value set by SetMinSum, regardless of whether Collect succeeded or reverted
        assertTrue(c.MinSum() == minSum, "MinSum should remain unchanged after Collect");
    }
}

